{
  "avaliacoes": [
    {
      "id": "Eb2b9ad7c7aba75a8",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No sistema DICAS descrito, a diferença de rigidez entre linhas de proa e de popa gera complacência angular, o que o texto apresenta como indicação para regiões onde o mar crítico predomina em uma direção.",
          "trechos": [
            "Eb2b9ad7c7aba75a8:0:700"
          ],
          "condicoes": [
            "aplica-se ao sistema DICAS descrito na fonte",
            "a indicação mencionada depende de predominância direcional do mar crítico"
          ],
          "limites": [
            "a fonte não relaciona essa complacência a critérios de inspeção, fadiga, ruptura ou contingência",
            "o trecho não apresenta método de verificação dessa predominância ambiental"
          ]
        },
        {
          "proposicao": "A escolha entre linhas em catenária livre e em taut-leg impacta significativamente a deriva do sistema e o raio de ancoragem.",
          "trechos": [
            "Eb2b9ad7c7aba75a8:0:700",
            "Eb2b9ad7c7aba75a8:700:1393"
          ],
          "condicoes": [
            "aplica-se à comparação entre configurações de linhas de ancoragem feita pela fonte"
          ],
          "limites": [
            "o excerto não fornece valores de carregamento, fadiga, vida útil ou limites operacionais",
            "não há tratamento de inspeção aérea ou submarina"
          ]
        },
        {
          "proposicao": "No sistema taut-leg descrito, as linhas permanecem bem tracionadas e sem segmento apoiado no leito marinho, reduzindo o passeio do sistema, mas transferindo à âncora solicitações verticais que não ocorrem no sistema convencional.",
          "trechos": [
            "Eb2b9ad7c7aba75a8:700:1393"
          ],
          "condicoes": [
            "aplica-se ao sistema taut-leg descrito pela fonte"
          ],
          "limites": [
            "o trecho não desenvolve consequências dessas cargas verticais para integridade, arrancamento, inspeção ou substituição da âncora",
            "a redução de passeio é apresentada sem quantificação"
          ]
        }
      ]
    },
    {
      "id": "E0f46e53a5df4e268",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na ancoragem taut-leg descrita, as extremidades inferiores das linhas são fixadas por estacas de sucção, âncoras com resistência vertical ou estacas de fundeio.",
          "trechos": [
            "E0f46e53a5df4e268:0:693"
          ],
          "condicoes": [
            "aplica-se à configuração taut-leg apresentada na fonte"
          ],
          "limites": [
            "o trecho não traz critérios de seleção entre esses tipos de fundação",
            "não há requisitos de instalação, inspeção, reparo ou capacidade pós-falha"
          ]
        },
        {
          "proposicao": "O texto afirma que a ancoragem taut-leg é geralmente empregada em plataformas semissubmersíveis e navios FPSO.",
          "trechos": [
            "E0f46e53a5df4e268:0:693"
          ],
          "condicoes": [
            "aplica-se ao panorama de uso apresentado pela fonte"
          ],
          "limites": [
            "o trecho não explicita em quais condições ambientais, profundidades ou arranjos submarinos esse emprego é preferível",
            "não há relação direta com corrosão, desgaste, fadiga ou contingência"
          ]
        },
        {
          "proposicao": "Na ancoragem em ponto único descrita, a embarcação pode se alinhar ao carregamento ambiental, minimizando forças no casco; entre os tipos citados estão turret, CALM e SALM, e no turret todas as linhas de ancoragem e risers são presos ao próprio turret, permitindo giro da embarcação em torno das linhas.",
          "trechos": [
            "E0f46e53a5df4e268:1385:2085",
            "E0f46e53a5df4e268:2085:2288"
          ],
          "condicoes": [
            "aplica-se à classificação e descrição de SPM presentes na fonte"
          ],
          "limites": [
            "a minimização de forças no casco é qualitativa",
            "o excerto não aborda limites de heading, cargas em linhas, inspeção do turret ou resposta a extremos ambientais"
          ]
        }
      ]
    },
    {
      "id": "E33b507c68b1b58d2",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte distingue turret interno e turret externo como variantes do sistema de ancoragem de FPSO, diferenciando-os pela integração estrutural ao navio e pela posição da estrutura associada ao sistema de rolamentos.",
          "trechos": [
            "E33b507c68b1b58d2:0:698"
          ],
          "condicoes": [
            "aplica-se à tipologia de turret descrita na fonte"
          ],
          "limites": [
            "o trecho não apresenta implicações dessa distinção para inspeção, manutenção ou reparo",
            "não há comparação de desempenho sob falha ou condição extrema"
          ]
        },
        {
          "proposicao": "No turret externo descrito, linhas de ancoragem, mangotes de transferência, risers e umbilicais se conectam à base do sistema de modo que o navio possa girar livremente ao redor dessa base sem interromper a produção.",
          "trechos": [
            "E33b507c68b1b58d2:698:1392"
          ],
          "condicoes": [
            "aplica-se ao arranjo de turret externo descrito pela fonte"
          ],
          "limites": [
            "o trecho não informa limites de rotação, restrições operacionais, monitoramento ou consequências de falha dos componentes conectados",
            "não há conteúdo sobre corrosão, desgaste ou fadiga"
          ]
        },
        {
          "proposicao": "A fonte descreve o spread mooring como sistema de ancoragem distribuída com quatro grupos de linhas, normalmente dispostos de forma simétrica, ligados à proa e à popa do FPSO.",
          "trechos": [
            "E33b507c68b1b58d2:698:1392"
          ],
          "condicoes": [
            "aplica-se à descrição de spread mooring adotada pela fonte"
          ],
          "limites": [
            "a configuração apresentada não deve ser extrapolada como única forma possível de spread mooring",
            "o trecho não aborda distribuição de cargas, redundância, falha de linha ou inspeção submarina"
          ]
        }
      ]
    },
    {
      "id": "E2777b898f1f4711a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Segundo a fonte, amarrações convencionais de semissubmersíveis e spars permitem grandes movimentos de heave em condições ambientais severas e isso impõe problemas à configuração do riser, podendo resultar em produção ineficiente.",
